class RemoveFilteredNamedGroupingPolicyTests {

    private Enforcer enforcer;
    private String policyPath = "src/test/resources/grouping_policy.csv";
    private String modelPath = "src/test/resources/model.conf";

    @BeforeEach
    void setUp() throws IOException {
        // Create a temporary policy file for testing
        File file = new File(policyPath);
        file.getParentFile().mkdirs();
        try (FileWriter writer = new FileWriter(file)) {
            writer.write("p, alice, data1, read\n");
            writer.write("p, bob, data2, write\n");
            writer.write("g, alice, data_group_admin\n");
            writer.write("g, bob, data_group_user\n");
            writer.write("g, data_group_admin, data1\n");
            writer.write("g, data_group_user, data2\n");
        }

        // Initialize enforcer
        enforcer = new Enforcer(modelPath, new FileAdapter(policyPath));
    }

    @Test
    void testRemoveFilteredNamedGroupingPolicySuccess() {
        // Verify initial state
        List<List<String>> policies = enforcer.getNamedGroupingPolicy("g");
        assertEquals(4, policies.size());

        // Remove policy where user is "bob"
        boolean result = enforcer.removeFilteredNamedGroupingPolicy("g", 0, "bob");

        assertTrue(result);
        policies = enforcer.getNamedGroupingPolicy("g");
        assertEquals(3, policies.size());

        // Verify specific removal
        assertFalse(policies.contains(List.of("bob", "data_group_user")));
    }

