class RemoveMatchesTests {

    @Test
    void testRemoveMatchesClearsMatchedByAndUpdatesMatchedInLinkedRoles() throws Exception {
        // Create Role A
        Role roleA = createRole("roleA");

        // Create Role B and C
        Role roleB = createRole("roleB");
        Role roleC = createRole("roleC");

        // Manually inject relationships: A is matched by B and C
        // This simulates: B matches A, C matches A
        addMatched(roleB, roleA);
        addMatched(roleC, roleA);

        // Verify setup state
        assertEquals(1, getMatchedMap(roleB).size());
        assertEquals(1, getMatchedMap(roleC).size());
        assertTrue(getMatchedMap(roleB).containsKey("roleA"));
        assertTrue(getMatchedMap(roleC).containsKey("roleA"));
        assertEquals(2, getMatchedByMap(roleA).size());

        // Invoke the method under test on roleA
        invokeRemoveMatches(roleA);

        // Verify that roleA's matchedBy map is cleared
        assertEquals(0, getMatchedByMap(roleA).size());

        // Verify that roleB and roleC no longer have roleA in their matched map
        assertEquals(0, getMatchedMap(roleB).size());
        assertEquals(0, getMatchedMap(roleC).size());
    }

    @Test
    void testRemoveMatchesWithEmptyMatchedBy() throws Exception {
        Role role = createRole("role");

        // Verify state
        assertEquals(0, getMatchedByMap(role).size());

        // Invoke the method under test
        invokeRemoveMatches(role);

        // Verify state remains empty
        assertEquals(0, getMatchedByMap(role).size());
    }

    @Test
    void testRemoveMatchesWithMultipleLinksInSingleRole() throws Exception {
        // Create Role A
        Role roleA = createRole("roleA");

        // Create Role B
        Role roleB = createRole("roleB");

        // Manually inject relationships: A is matched by B multiple times (e.g. different conditions or duplicates)
        // The map structure keys are strings, so we add different keys to simulate multiple links or distinct match entries
        addMatched(roleB, roleA, "condition1");
        addMatched(roleB, roleA, "condition2");

        // Verify setup state
        assertEquals(2, getMatchedMap(roleB).size());
        assertEquals(2, getMatchedByMap(roleA).size());

        // Invoke the method under test on roleA
        invokeRemoveMatches(roleA);

        // Verify that roleA's matchedBy map is cleared
        assertEquals(0, getMatchedByMap(roleA).size());

        // Verify that roleB's matched map is cleared of all entries related to roleA
        assertEquals(0, getMatchedMap(roleB).size());
    }

    // --- Helper methods to access protected/private fields and methods ---

    private Role createRole(String name) {
        try {
            java.lang.reflect.Constructor<Role> constructor = Role.class.getDeclaredConstructor(String.class);
            constructor.setAccessible(true);
            return constructor.newInstance(name);
        } catch (Exception e) {
            throw new RuntimeException("Failed to instantiate Role", e);
        }
    }

    private Map<String, Role> getMatchedByMap(Role role) throws Exception {
        Field field = Role.class.getDeclaredField("matchedBy");
        field.setAccessible(true);
        @SuppressWarnings("unchecked")
        Map<String, Role> map = (Map<String, Role>) field.get(role);
        return map;
    }

    private Map<String, Role> getMatchedMap(Role role) throws Exception {
        Field field = Role.class.getDeclaredField("matched");
        field.setAccessible(true);
        @SuppressWarnings("unchecked")
        Map<String, Role> map = (Map<String, Role>) field.get(role);
        return map;
    }

    private void addMatched(Role source, Role target) throws Exception {
        addMatched(source, target, target.name);
    }

    private void addMatched(Role source, Role target, String key) throws Exception {
        // Add to source.matched
        Map<String, Role> matchedMap = getMatchedMap(source);
        matchedMap.put(key, target);

        // Add to target.matchedBy
        Map<String, Role> matchedByMap = getMatchedByMap(target);
        matchedByMap.put(source.name, source);
    }

    private void invokeRemoveMatches(Role role) throws Exception {
        Method method = Role.class.getDeclaredMethod("removeMatches");
        method.setAccessible(true);
        method.invoke(role);
